pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address actor, bytes memory data) public {
        vm.assume(actor != address(0));
        vm.assume(actor != c.Owner());
        vm.deal(actor, 0);
        vm.prank(actor);
        bool ok;
        try c.Command(address(0), data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
